/**
 * Experiment Strength: how well validated an EXPERIMENT is, universal to every
 * student. Nothing here is personalised, and nothing here is generated by a
 * model — every input is a stored, human-verified record:
 *
 *   RoleBlueprint      what we believe the career actually involves
 *   CareerSource       the documented sources that belief rests on
 *   ExperimentValidation  which parts of the blueprint this experiment maps to
 *   ProfessionalExperimentReview  what professionals said about the mapping
 *
 * Rules held here on purpose:
 *  - AI-drafted content starts at Level 0 and cannot climb without records.
 *  - Usage volume alone never promotes an experiment. Field calibration is a
 *    stored admin decision (`field_calibrated`), not a threshold.
 *  - Weights are configuration and are versioned, so a score calculated under an
 *    older version is never silently reinterpreted under a newer one.
 *  - A score is withheld rather than guessed when there is almost nothing to
 *    read: false precision is worse than "Validation Still Developing".
 */

export const STRENGTH_SCORING_VERSION = 'exp-strength-1';

/** Starting weights. Configuration, tunable, versioned when changed. */
export const STRENGTH_WEIGHTS = {
  source_grounding: 20,
  professional_validation: 30,
  role_realism: 20,
  dimension_mapping: 15,
  field_calibration: 15,
};

export const STRENGTH_LEVELS = [
  { id: 'developing', label: 'Developing', min: 0 },
  { id: 'grounded', label: 'Grounded', min: 40 },
  { id: 'strong', label: 'Strong', min: 62 },
  { id: 'highly_validated', label: 'Highly Validated', min: 82 },
];

/** The five validation levels, student-facing wording included. */
export const VALIDATION_LEVELS = [
  { level: 0, id: 'ai_draft', label: 'Early Draft', note: 'This experiment has not yet completed Unscripted\u2019s full validation process.' },
  { level: 1, id: 'source_grounded', label: 'Source Grounded', note: 'Mapped to a role blueprint supported by verified occupational or current-market sources.' },
  { level: 2, id: 'professional_reviewed', label: 'Professionally Reviewed', note: 'A verified professional with relevant recent experience has reviewed this experiment.' },
  { level: 3, id: 'multi_professional', label: 'Multi-Professional Validated', note: 'Several relevant professionals reviewed this independently using the same rubric.' },
  { level: 4, id: 'field_calibrated', label: 'Field Calibrated', note: 'Professionally validated, and reviewed against how it has actually performed with students.' },
];

export const validationLevelMeta = (n) => VALIDATION_LEVELS[Math.max(0, Math.min(4, Number(n) || 0))];

/** Below this, aggregate student statistics are not shown at all. */
export const MIN_FIELD_SAMPLE = 25;

const SOURCE_RECENCY_MONTHS = 30;
const num = (v) => (typeof v === 'number' && Number.isFinite(v) ? v : null);
const clamp01 = (n) => Math.max(0, Math.min(1, n));
const avg = (xs) => (xs.length ? xs.reduce((a, b) => a + b, 0) / xs.length : null);
const pct = (n) => Math.round(n);

const monthsSince = (date) => {
  const t = date ? new Date(date).getTime() : NaN;
  if (!Number.isFinite(t)) return null;
  return (Date.now() - t) / (1000 * 60 * 60 * 24 * 30.44);
};

/** Reviews that count: approved, and tied to the experiment version in play. */
export function countingReviews(reviews = [], experimentVersion = null) {
  return (reviews || []).filter(r =>
    r?.approval_status === 'approved'
    && (experimentVersion == null || r.experiment_version == null || Number(r.experiment_version) === Number(experimentVersion)));
}

/** Which of the five levels the stored records support. Never speculative. */
export function validationLevelFrom({ validation, sources = [], reviews = [] }) {
  const verified = sources.filter(s => s.active_status !== 'retired' && s.source_verified_at);
  const grounded = Boolean(validation?.role_blueprint_id) && verified.length >= 1;
  const approved = countingReviews(reviews, validation?.experiment_version);
  if (!grounded) return 0;
  if (validation?.field_calibrated && approved.length >= 2) return 4;
  if (approved.length >= 2) return 3;
  if (approved.length >= 1) return 2;
  return 1;
}

/**
 * The score, its components, and the reasons behind each one.
 * `sufficient` is false when there is too little on file to show a number.
 */
export function experimentStrength({ validation, sources = [], reviews = [], effectiveness = null } = {}) {
  const W = STRENGTH_WEIGHTS;
  const verified = (sources || []).filter(s => s.active_status !== 'retired' && s.source_verified_at);
  const approved = countingReviews(reviews, validation?.experiment_version);
  const mapped = validation?.decision_dimension_ids?.length || validation?.work_characteristics_tested?.length || 0;
  const notRepresented = validation?.career_characteristics_not_represented?.length || 0;

  // 1. Source grounding — how many verified sources, and how current they are.
  const fresh = verified.filter(s => {
    const m = monthsSince(s.source_verified_at);
    return m !== null && m <= SOURCE_RECENCY_MONTHS;
  });
  const kinds = new Set(verified.map(s => s.source_type));
  const source_grounding = validation?.role_blueprint_id
    ? W.source_grounding * clamp01(
        0.55 * Math.min(1, verified.length / 3)
        + 0.25 * (verified.length ? fresh.length / verified.length : 0)
        + 0.20 * Math.min(1, (kinds.size - 1) / 2))
    : 0;

  // 2. Professional validation — reviewer count, and whether they agree.
  const spread = (key) => {
    const xs = approved.map(r => num(r[key])).filter(v => v !== null);
    return xs.length >= 2 ? Math.max(...xs) - Math.min(...xs) : null;
  };
  const disagreement = [spread('realism_rating'), spread('workstyle_validity_rating')].filter(v => v !== null);
  const agreement = disagreement.length ? clamp01(1 - avg(disagreement) / 3) : 0.7;
  const roles = new Set(approved.map(r => (r.reviewer_role || '').toLowerCase()).filter(Boolean));
  const professional_validation = W.professional_validation * clamp01(
    0.6 * Math.min(1, approved.length / 3)
    + 0.25 * agreement
    + 0.15 * Math.min(1, Math.max(0, roles.size - 1)));

  // 3. Role realism — what the reviewers actually rated, out of 5.
  const realismInputs = [
    avg(approved.map(r => num(r.realism_rating)).filter(v => v !== null)),
    avg(approved.map(r => num(r.entry_level_realism_rating)).filter(v => v !== null)),
    avg(approved.map(r => num(r.terminology_rating)).filter(v => v !== null)),
  ].filter(v => v !== null);
  const misleading = approved.reduce((n, r) => n + (r.misleading_elements?.length || 0), 0);
  const role_realism = realismInputs.length
    ? Math.max(0, W.role_realism * (clamp01((avg(realismInputs) - 1) / 4) - Math.min(0.25, misleading * 0.08)))
    : 0;

  // 4. Dimension mapping quality — is it mapped, reviewed, and honest about
  //    what it does NOT test?
  const dimension_mapping = W.dimension_mapping * clamp01(
    0.45 * Math.min(1, mapped / 3)
    + 0.25 * (notRepresented >= 2 ? 1 : notRepresented ? 0.5 : 0)
    + 0.2 * (validation?.mapping_reviewed ? 1 : 0)
    + 0.1 * (avg(approved.map(r => num(r.workstyle_validity_rating)).filter(v => v !== null)) ? clamp01((avg(approved.map(r => num(r.workstyle_validity_rating)).filter(v => v !== null)) - 1) / 4) : 0));

  // 5. Field calibration — an admin decision, backed by a real sample.
  const started = num(effectiveness?.students_started) || 0;
  const sample = started >= MIN_FIELD_SAMPLE;
  const field_calibration = validation?.field_calibrated && sample
    ? W.field_calibration * clamp01(
        0.5
        + 0.25 * clamp01(num(effectiveness?.completion_rate) ?? 0)
        + 0.25 * clamp01((num(effectiveness?.student_reported_usefulness) ?? 0) / 5))
    : 0;

  const component_scores = {
    source_grounding: pct(source_grounding),
    professional_validation: pct(professional_validation),
    role_realism: pct(role_realism),
    dimension_mapping: pct(dimension_mapping),
    field_calibration: pct(field_calibration),
  };
  const score = Object.values(component_scores).reduce((a, b) => a + b, 0);
  const level = [...STRENGTH_LEVELS].reverse().find(l => score >= l.min) || STRENGTH_LEVELS[0];
  const validation_level = validationLevelFrom({ validation, sources, reviews });

  // Enough on file to show a number at all: a blueprint mapping plus either a
  // verified source or an approved review.
  const sufficient = Boolean(validation?.role_blueprint_id) && (verified.length >= 1 || approved.length >= 1);

  const reasons = [
    { met: verified.length >= 1, text: verified.length ? `Grounded in ${verified.length} verified source${verified.length === 1 ? '' : 's'}` : 'Not yet grounded in verified sources' },
    { met: approved.length >= 1, text: approved.length ? 'Professionally reviewed' : 'Not yet professionally reviewed' },
    { met: approved.length >= 2, text: approved.length >= 2 ? `Reviewed by ${approved.length} relevant professionals` : 'Reviewed by fewer than two professionals' },
    { met: mapped >= 2 && notRepresented >= 1, text: mapped ? 'Career dimensions clearly mapped' : 'Career dimensions not yet mapped' },
    { met: Boolean(validation?.field_calibrated && sample), text: validation?.field_calibrated && sample ? 'Field calibrated against student results' : 'Not yet field calibrated' },
  ];

  return {
    scoring_version: STRENGTH_SCORING_VERSION,
    score: sufficient ? score : null,
    raw_score: score,
    level_id: sufficient ? level.id : 'developing',
    level_label: sufficient ? level.label : 'Validation Still Developing',
    sufficient,
    component_scores,
    component_max: { ...W },
    validation_level,
    validation_level_meta: validationLevelMeta(validation_level),
    verified_source_count: verified.length,
    reviewer_count: approved.length,
    last_reviewed_at: approved.map(r => r.review_date).filter(Boolean).sort().slice(-1)[0]
      || validation?.last_validated_at || null,
    field_sample_shown: sample,
    reasons,
    // How much trust downstream evidence should place in a result from this
    // experiment. Never zero: a student's own reaction is always worth keeping.
    evidence_trust: sufficient ? clamp01(0.55 + (score / 100) * 0.45) : 0.5,
  };
}

/** A stored snapshot, for provenance at the moment a student completed it. */
export function strengthSnapshot(strength, validation) {
  return {
    experiment_version: validation?.experiment_version ?? 1,
    experiment_strength_score: strength.score,
    experiment_strength_level: strength.level_id,
    validation_level: strength.validation_level,
    scoring_version: strength.scoring_version,
    role_blueprint_version: validation?.role_blueprint_version ?? null,
    component_scores: strength.component_scores,
    calculated_at: new Date().toISOString(),
  };
}

export default experimentStrength;